"""Regression cases from the independent 2026-11-04 numerical audit."""
import unittest
import warnings
import numpy as np
from pairpulse import (SauterPulse, PulseTrain, solve_dirac_mode, solve_qke_mode,
                       sauter_exact_occupation, sauter_log_occupation, integrated_density)


class RegressionTests(unittest.TestCase):
    def test_exact_cancellation_regressions(self):
        # Independent 100-digit reference values, not generated by this helper.
        cases=[(10.,1e-12,.01,1.,9.4836235792599082704e-33),
               (.7,1e4,1e3,1.,.99968589007749571843),
               (1e8,1.,1e-9,1.,9.6774067796343010987e-51),
               (1.,1.,1.,1e-8,.49999999089596358679)]
        for p,e,t,m,ref in cases:
            with self.subTest(p=p,E0=e,tau=t,mass=m):
                value=sauter_exact_occupation(p,SauterPulse(e,t),mass=m)
                self.assertLess(abs(value-ref)/ref,5e-13)

    def test_log_occupation_retains_underflowed_yields(self):
        pulse=SauterPulse(.01,100)
        value=sauter_log_occupation(100.,pulse)
        self.assertTrue(np.isfinite(value));self.assertLess(value,-745)
        self.assertEqual(sauter_exact_occupation(100.,pulse),0.)
        self.assertEqual(sauter_log_occupation(0,SauterPulse(0,1)),-np.inf)

    def test_unsupported_exact_kinematics_are_explicit(self):
        with self.assertRaises(ValueError):
            sauter_exact_occupation(1,SauterPulse(1e308,1e308))
        with self.assertRaises(TypeError):
            sauter_exact_occupation(0,PulseTrain([SauterPulse(.3,2)]))

    def test_field_tails_do_not_overflow(self):
        with np.errstate(over='raise',invalid='raise'):
            values=SauterPulse(.3,1e-4).field(np.array([-1e6,0,1e6]))
        np.testing.assert_allclose(values,[0,.3,0],rtol=0,atol=0)

    def test_narrow_custom_pulse_absolute_cap(self):
        base=SauterPulse(1000,1e-4)
        class Custom:
            field=staticmethod(base.field)
            potential=staticmethod(base.potential)
            def time_window(self,tail_factor=12):return -.011,.013
        reference=sauter_exact_occupation(0,base)
        result=solve_qke_mode(0,Custom(),max_step=1e-4/8)
        self.assertLess(abs(result.occupation-reference),2e-11)
        with self.assertWarnsRegex(UserWarning,'resolution_scale'):
            solve_qke_mode(0,Custom())

    def test_builtin_feature_cap(self):
        from pairpulse.solvers import _maximum_step
        pulse=PulseTrain([SauterPulse(.3,.001,-1),SauterPulse(.3,2,1)])
        ti,tf=pulse.time_window()
        self.assertLessEqual(_maximum_step(ti,tf,0,1,1,pulse),.001/8)

    def test_bad_absolute_caps_and_endpoints(self):
        class Bad(SauterPulse):
            def time_window(self,tail_factor=12):return 1.,-1.
        for solve in (solve_dirac_mode,solve_qke_mode):
            for value in (0,-1,np.nan,np.inf):
                with self.assertRaises(ValueError):solve(0,SauterPulse(.3,1),max_step=value)
            with self.assertRaises(ValueError):solve(0,Bad(.3,1))

    def test_density_measure_sorting_and_rejection(self):
        # Integral of a constant on [-1,1] is 2/(2*pi).
        self.assertAlmostEqual(integrated_density([1,-1,0],[1,1,1]),1/np.pi)
        for p,f in [([0,np.nan,1],[.1,.2,.3]),([0,1],[0,np.inf]),([0,0,1],[0,1,0])]:
            with self.assertRaises(ValueError):integrated_density(p,f)
        with self.assertRaises(ValueError):integrated_density([0,1],[-1,-1],check_bounds=True)
        self.assertLess(integrated_density([0,1],[-1e-12,-1e-12],check_bounds=True),0)

    def test_gauge_polarity_and_mass_charge_scaling(self):
        base=SauterPulse(.3,1.1)
        class Shifted:
            def field(self,t):return base.field(t)
            def potential(self,t):return base.potential(t)+3
            def time_window(self,tail_factor=12):return base.time_window(tail_factor)
            def resolution_scale(self):return base.duration
        class Reversed(Shifted):
            def field(self,t):return -base.field(t)
            def potential(self,t):return -base.potential(t)
        for solve in (solve_dirac_mode,solve_qke_mode):
            a=solve(.7,base).occupation
            self.assertLess(abs(a-solve(3.7,Shifted()).occupation),1e-10)
            self.assertLess(abs(a-solve(-.7,Reversed()).occupation),1e-10)
            a=solve(.6,SauterPulse(.4,.8),mass=2,charge=3).occupation
            b=solve(.3,SauterPulse(.3,1.6)).occupation
            self.assertLess(abs(a-b),1e-10)

if __name__=='__main__':unittest.main()
